WITH scored AS (SELECT id, channel, starts_on, ends_on, FIRST_VALUE(channel, TRUE) OVER (PARTITION BY channel ORDER BY starts_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_channel, LEAD(discount_pct, 2) OVER (ORDER BY discount_pct, id) AS next_discount_pct, AVG(discount_pct) OVER (PARTITION BY promo_code ORDER BY discount_pct, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS discount_pct_avg_3_prior FROM promotions) SELECT id, starts_on, first_known_channel, next_discount_pct, discount_pct_avg_3_prior FROM scored ORDER BY id NULLS LAST;
